    base = []
    for r in range(19):
        row = board_rows[r]
        if len(row) != 19:
            return False
        base.extend(row)
    NB = []
    for p in range(361):
        r = p // 19
        c = p - r * 19
        l = []
        if r > 0:
            l.append(p - 19)
        if r < 18:
            l.append(p + 19)
        if c > 0:
            l.append(p - 1)
        if c < 18:
            l.append(p + 1)
        NB.append(l)

    def chain(bd, p):
        t = bd[p]
        st = [p]
        mk = {p: 1}
        lb = {}
        i = 0
        while i < len(st):
            q = st[i]
            i += 1
            for z in NB[q]:
                u = bd[z]
                if u == '.':
                    lb[z] = 1
                elif u == t and z not in mk:
                    mk[z] = 1
                    st.append(z)
        return st, list(lb), mk

    def place(bd, p, t):
        o = 'B' if t == 'W' else 'W'
        bd[p] = t
        cap = 0
        for z in NB[p]:
            if bd[z] != o:
                continue
            free = 0
            for y in NB[z]:
                if bd[y] == '.':
                    free = 1
                    break
            if free:
                continue
            st, lb, mk = chain(bd, z)
            if not lb:
                for q in st:
                    bd[q] = '.'
                cap += len(st)
        for y in NB[p]:
            if bd[y] == '.':
                return cap
        st, lb, mk = chain(bd, p)
        if not lb:
            bd[p] = '.'
            return -1
        return cap

    def esc(bd, dp, D, mk):
        v = 0
        for z in NB[dp]:
            u = bd[z]
            if u == '.':
                v += 1
            elif u == D and z not in mk:
                v += 3
        return v

    def caught(p, A, D):
        bd = base[:]
        for step in range(18):
            st, lb, mk = chain(bd, p)
            n = len(lb)
            if n == 0:
                return 1
            if n >= 3:
                return 0
            if n == 1:
                if place(bd, lb[0], A) < 0:
                    return 0
                return 1
            a = lb[0]
            b = lb[1]
            if esc(bd, b, D, mk) <= esc(bd, a, D, mk):
                ap = a
                other = b
            else:
                ap = b
                other = a
            c = place(bd, ap, A)
            if c < 0:
                ap = other
                c = place(bd, ap, A)
                if c < 0:
                    return 0
            if c > 0:
                continue
            ast, alb, amk = chain(bd, ap)
            if len(alb) <= 1:
                return 0
            st2, lb2, mk2 = chain(bd, p)
            if len(lb2) == 0:
                return 1
            if len(lb2) >= 2:
                continue
            c2 = place(bd, lb2[0], D)
            if c2 < 0:
                return 1
            if c2 > 0:
                return 0
        return 0

    tg = {'B': [], 'W': []}
    seen = [0] * 361
    for p in range(361):
        t = base[p]
        if t == '.' or seen[p]:
            continue
        st, lb, mk = chain(base, p)
