    stones = []
    nlib = []
    neye = []
    openn = []
    nB = 0
    nW = 0
    for r in range(19):
        row = g[r]
        for c in range(19):
            t = row[c]
            if t == '.':
                continue
            if t == 'B':
                nB += 1
            else:
                nW += 1
            p = r * 19 + c
            if cid[p] >= 0:
                continue
            k = len(col)
            cid[p] = k
            st = [p]
            lb = {}
            i = 0
            while i < len(st):
                q = st[i]
                i += 1
                qr = q // 19
                qc = q - qr * 19
                for dr, dc in D4:
                    ar = qr + dr
                    ac = qc + dc
                    if ar < 0 or ar > 18 or ac < 0 or ac > 18:
                        continue
                    z = ar * 19 + ac
                    u = g[ar][ac]
                    if u == '.':
                        lb[z] = 1
                    elif u == t and cid[z] < 0:
                        cid[z] = k
                        st.append(z)
            ey = 0
            op = 0
            for z in lb:
                s = csize[comp[z]]
                if s > op:
                    op = s
                zr = z // 19
                zc = z - zr * 19
                ok = 1
                for dr, dc in D4:
                    ar = zr + dr
                    ac = zc + dc
                    if ar < 0 or ar > 18 or ac < 0 or ac > 18:
                        continue
                    if g[ar][ac] != t:
                        ok = 0
                        break
                if ok:
                    ey += 1
            col.append(t)
            stones.append(st)
            nlib.append(len(lb))
            neye.append(ey)
            openn.append(op)

    if nB < 8 or nW < 8:
        return False

    offs = []
    for dr in range(-3, 4):
        for dc in range(-3, 4):
            if dr == 0 and dc == 0:
                continue
            a = -dr if dr < 0 else dr
            b = -dc if dc < 0 else dc
            m = a if a > b else b
            offs.append((dr, dc, 4 - m))

    sB = 0.0
    sW = 0.0
    for k in range(len(col)):
        t = col[k]
        o = 'W' if t == 'B' else 'B'
        fr = 0
        en = 0
        for q in stones[k]:
            qr = q // 19
            qc = q - qr * 19
            for dr, dc, w in offs:
                ar = qr + dr
                ac = qc + dc
                if ar < 0 or ar > 18 or ac < 0 or ac > 18:
                    continue
                u = g[ar][ac]
                if u == o:
                    en += w
                elif u == t and cid[ar * 19 + ac] != k:
                    fr += w
        depth = (en - fr) / float(en + fr + 8)
        if depth <= 0.1:
            continue
        L = nlib[k]
        sz = len(stones[k])
        ey = neye[k]
        op = openn[k]
        if ey >= 2:
            h = 1.0
        elif L >= 5 and op >= 10:
            h = 0.85
        elif L >= 4 and op >= 10:
            h = 0.6
        elif L >= 6:
            h = 0.5
        elif L >= 4 and op >= 5:
            h = 0.35
        else:
            h = 0.0
        if h <= 0.0:
            continue
        m = sz if sz < 8 else 8
        v = h * m * depth
        if t == 'B':
            sB += v
        else:
            sW += v

    if color == 'B':
        return sB > sW
    return sW > sB

MOTIF_NAME = 'settled two-eye life share'
MOTIF_DESCRIPTION = 'After the side to move lifts off any enemy chain already in atari, every empty region walled in by a single colour is measured as eye space (false one-point eyes discarded and small enclosed enemy stones inside treated as dead), chains that share eye space are welded into one living group, and the evaluated side has a larger share of its army settled with two eyes worth of eye space than the opponent has of its own.'

def motif(board_rows: list[str], color: str) -> bool:
    if len(board_rows) != 19 or (color != 'B' and color != 'W'):
        return False
    g = []
    for row in board_rows:
        if len(row) != 19:
            return False
        g.extend(row)
    opp = 'W' if color == 'B' else 'B'

    NB = []
    DG = []
    for p in range(361):
        r = p // 19
        c = p - r * 19
        l = []
        if r > 0:
            l.append(p - 19)
        if r < 18:
            l.append(p + 19)
        if c > 0:
            l.append(p - 1)
        if c < 18:
            l.append(p + 1)
        NB.append(l)
        d = []
        ob = 0
        for dr in (-1, 1):
            for dc in (-1, 1):
                ar = r + dr
                ac = c + dc
                if 0 <= ar < 19 and 0 <= ac < 19:
                    d.append(ar * 19 + ac)
                else:
                    ob = 1
        DG.append((d, ob))

    h = g[:]
    seen = [0] * 361
    for p in range(361):
        if g[p] != opp or seen[p]:
            continue
        st = [p]
        seen[p] = 1
        lb = {}
        i = 0
        while i < len(st):
            q = st[i]
            i += 1
            for z in NB[q]:
                u = g[z]
                if u == '.':
                    lb[z] = 1
                elif u == opp and not seen[z]:
                    seen[z] = 1
                    st.append(z)
        if len(lb) <= 1:
            for q in st:
                h[q] = '.'

    cid = [-1] * 361
    csz = []
    ccl = []
    clb = []
    for p in range(361):
        t = h[p]
        if t == '.' or cid[p] >= 0:
            continue
        k = len(csz)
        cid[p] = k
        st = [p]
        lb = {}
        i = 0
        while i < len(st):
            q = st[i]
            i += 1
            for z in NB[q]:
                u = h[z]
                if u == '.':
                    lb[z] = 1
                elif u == t and cid[z] < 0:
                    cid[z] = k
                    st.append(z)
        csz.append(len(st))
        ccl.append(t)
        clb.append(lb)
    n = len(csz)
    if n < 2:
        return False

    T = {'B': 0, 'W': 0}
    for i in range(n):
        T[ccl[i]] += csz[i]
    if T['B'] < 10 or T['W'] < 10:
        return False

    par = list(range(n))

    def find(x):
        while par[x] != x:
            par[x] = par[par[x]]
            x = par[x]
        return x

    rid = [-1] * 361
    reg = []
    for p in range(361):
        if h[p] != '.' or rid[p] >= 0:
            continue
        k = len(reg)
        rid[p] = k
        st = [p]
        bd = {}
        i = 0
        while i < len(st):
            q = st[i]
            i += 1
            for z in NB[q]:
                if h[z] == '.':
                    if rid[z] < 0:
                        rid[z] = k
                        st.append(z)
                else:
                    bd[cid[z]] = 1
        reg.append((st, list(bd)))

    vals = []
    for k in range(len(reg)):
        st = reg[k][0]
        bd = reg[k][1]
        pts = {}
        for q in st:
            pts[q] = 1
        live = []
        cols = {}
        for ci in bd:
            ins = 1
            for z in clb[ci]:
                if z not in pts:
                    ins = 0
                    break
            if ins and len(clb[ci]) <= 3 and csz[ci] <= 6:
                continue
            live.append(ci)
            cols[ccl[ci]] = 1
        s = len(st)
        if len(cols) != 1 or not live or s > 25:
            continue
        t = ccl[live[0]]
        if s == 1:
            o = 'W' if t == 'B' else 'B'
            dd = DG[st[0]][0]
            ob = DG[st[0]][1]
            bad = 0
            for z in dd:
                if h[z] == o:
                    bad += 1
            if bad > (0 if ob else 1):
                continue
            v = 1.0
        elif s == 2:
            v = 1.0
        elif s == 3:
            v = 1.5
        else:
            v = 2.0
        vals.append((v, live))
        for j in range(1, len(live)):
            a = find(live[0])
            b = find(live[j])
            if a != b:
                par[a] = b

    gv = {}
    for v, live in vals:
        rt = find(live[0])
        gv[rt] = gv.get(rt, 0.0) + v

    L = {'B': 0, 'W': 0}
    for i in range(n):
        if gv.get(find(i), 0.0) >= 2.0:
            L[ccl[i]] += csz[i]
    if L['B'] == 0 and L['W'] == 0:
        return False

    D = (L[color] / float(T[color]) - L[opp] / float(T[opp]))
    D += 0.5 * (L[color] - L[opp]) / float(T['B'] + T['W'])
    if color == 'B':
        return D > 0.04
    return D > -0.04

MOTIF_NAME = 'level on the count but ahead on doomed material'
MOTIF_DESCRIPTION = 'A plain nearest-stone count of the whole board with komi gives the evaluated side no lead at all, yet once hard material is cashed in - the prisoners implied by the stone-count parity, enemy chains in atari with the evaluated side to move, and enemy groups sealed into small spaces with no room for two eyes - the evaluated side comes out clearly ahead.'

def motif(board_rows: list[str], color: str) -> bool:
    if len(board_rows) != 19 or (color != 'B' and color != 'W'):
        return False
    for row in board_rows:
        if len(row) != 19:
            return False
    opp = 'W' if color == 'B' else 'B'
    cells = []
    for row in board_rows:
        for ch in row:
            cells.append(ch)
    NB = []
    for i in range(361):
        r = i // 19
        c = i - 19 * r
        l = []
        if r:
            l.append(i - 19)
        if r < 18:
            l.append(i + 19)
        if c:
            l.append(i - 1)
        if c < 18:
            l.append(i + 1)
        NB.append(l)

    nm = 0
    no = 0
    for ch in cells:
        if ch == color:
            nm += 1
        elif ch == opp:
            no += 1
    if nm + no < 24 or nm < 5 or no < 5:
        return False

    def dist(col):
        d = [200] * 361
        fr = []
        for i in range(361):
            if cells[i] == col:
                d[i] = 0
                fr.append(i)
        lev = 0
        while fr and lev < 30:
            nx = []
            nl = lev + 1
            for x in fr:
                for y in NB[x]:
                    if cells[y] == '.' and d[y] > nl:
                        d[y] = nl
                        nx.append(y)
            fr = nx
            lev = nl
        return d

    dm = dist(color)
    do = dist(opp)
    mine = 0
    theirs = 0
    for i in range(361):
        s = cells[i]
        if s == color:
            mine += 1
        elif s == opp:
            theirs += 1
        else:
            a = dm[i]
            b = do[i]
            if a < b:
                mine += 1
            elif b < a:
                theirs += 1
    L = (mine - theirs) + (7.0 if color == 'W' else -7.0)
    if L > 2.0 or L < -45.0:
        return False

    net = (nm - no) + (1 if color == 'W' else 0)

    cid = [-1] * 361
    ccol = []
    csz = []
    clb = []
    for i in range(361):
        s = cells[i]
        if s == '.' or cid[i] >= 0:
            continue
        k = len(ccol)
        cid[i] = k
        st = [i]
        n = 0
        lb = set()
        while st:
            x = st.pop()
            n += 1
            for y in NB[x]:
                t = cells[y]
                if t == '.':
                    lb.add(y)
                elif t == s and cid[y] < 0:
                    cid[y] = k
                    st.append(y)
        ccol.append(s)
        csz.append(n)
        clb.append(lb)
    nc = len(ccol)
    if nc < 2:
        return False

    rid = [-1] * 361
    rsz = []
    rbc = []
    for i in range(361):
        if cells[i] != '.' or rid[i] >= 0:
            continue
        q = len(rsz)
        rid[i] = q
        st = [i]
        n = 0
        bc = set()
        while st:
            x = st.pop()
            n += 1
            for y in NB[x]:
                t = cells[y]
                if t == '.':
                    if rid[y] < 0:
                        rid[y] = q
                        st.append(y)
                else:
                    bc.add(t)
        rsz.append(n)
        rbc.append(bc)

    par = list(range(nc))

    def find(a):
        while par[a] != a:
            par[a] = par[par[a]]
            a = par[a]
        return a

    pc = {}
    for i in range(361):
        if cells[i] != '.':
            continue
        ls = []
        for y in NB[i]:
            if cells[y] != '.':
                k = cid[y]
                if k not in ls:
                    ls.append(k)
        m = len(ls)
        for a in range(m):
            for b in range(a + 1, m):
                x = ls[a]
                y2 = ls[b]
                if ccol[x] != ccol[y2]:
                    continue
                key = (x, y2) if x < y2 else (y2, x)
                pc[key] = pc.get(key, 0) + 1
    for key in pc:
        if pc[key] >= 2:
            ra = find(key[0])
            rb = find(key[1])
            if ra != rb:
                par[ra] = rb

    gm = {}
    for k in range(nc):
        g = find(k)
        if g in gm:
            gm[g].append(k)
        else:
            gm[g] = [k]

    gain = 0.0
    loss = 0.0
    for g in gm:
        ks = gm[g]
        col = ccol[ks[0]]
        stones = 0
        libs = set()
        for k in ks:
            stones += csz[k]
            libs |= clb[k]
        regs = set()
        for p in libs:
            regs.add(rid[p])
        rs = 0
        eyes = 0
        for q in regs:
            rs += rsz[q]
            if len(rbc[q]) == 1 and col in rbc[q]:
                eyes += 1 if rsz[q] <= 2 else 2
        nl = len(libs)
        v = 0.0
        if eyes < 2 and rs <= 10 and nl <= 7:
            v = 2.0 * stones + (rs if rs < 6 else 6)
            if col == opp:
                gain += v
            else:
                loss += 0.9 * v
        elif nl == 1:
            if col == opp:
                gain += 2.0 * stones
            else:
                loss += 1.0 * stones
        elif nl == 2 and eyes < 1 and rs <= 22:
            if col == opp:
                gain += 0.9 * stones
            else:
                loss += 0.5 * stones

    tot = L + 0.5 * net + gain - loss
    return tot >= 5.5
